<template>
  <business-page title="出行管理" description="根据路书开始出行，并围绕单个出行实例完成定位匹配、打卡和状态流转。">
    <template #actions><el-button type="primary" icon="Location" @click="openStart">开始新出行</el-button></template>
    <section class="business-panel lookup-bar"><el-input-number v-model="journeyId" :min="1" controls-position="right" placeholder="出行实例 ID" /><el-button icon="Search" :loading="loading" @click="loadJourney">查询实例</el-button></section>
    <section class="business-panel content-panel">
      <page-state v-if="loading" type="loading" description="正在读取出行实例" /><page-state v-else-if="loadError" type="error" description="出行实例加载失败，请核对实例 ID 后重试。" action-text="重新查询" @action="loadJourney" /><page-state v-else-if="!detail" description="输入实例 ID 查询，或从右上角根据路书开始一次新出行。" />
      <template v-else>
        <header class="journey-header"><div><span>出行实例 #{{ detail.id }}</span><h2>路书 #{{ detail.routebookId }}</h2><p>开始于 {{ detail.startedAt || '--' }}</p></div><dict-tag :options="trip_journey_status" :value="detail.status" /></header>
        <div class="metric-row"><article><small>当前目标点</small><strong>{{ detail.currentPointId ?? '--' }}</strong></article><article><small>已打卡</small><strong>{{ detail.totalCheckinCount ?? 0 }}</strong></article><article><small>已跳过</small><strong>{{ detail.totalSkipCount ?? 0 }}</strong></article><article><small>当前顺序</small><strong>{{ detail.currentPointOrder ?? '--' }}</strong></article></div>
        <div class="journey-actions"><el-button @click="locationOpen = true">定位匹配</el-button><el-button @click="openCheckin()">手动打卡</el-button><el-button type="success" plain @click="finish">结束出行</el-button><el-button type="danger" plain @click="cancel">取消出行</el-button></div>
        <el-divider />
        <h3>点位进度</h3><page-state v-if="journeyPoints.length === 0" description="接口未返回点位进度数据。" /><el-table v-else :data="journeyPoints" stripe><el-table-column label="顺序" prop="pointOrder" width="80" /><el-table-column label="点位 ID" prop="pointId" width="110" /><el-table-column label="点位名称" prop="pointName" min-width="180" /><el-table-column label="状态" width="110"><template #default="scope"><dict-tag :options="trip_journey_point_status" :value="scope.row.status" /></template></el-table-column><el-table-column label="打卡方式" width="110"><template #default="scope"><dict-tag :options="trip_checkin_type" :value="scope.row.checkinType" /></template></el-table-column><el-table-column label="打卡时间" prop="checkinTime" min-width="170" /><el-table-column label="操作" width="180"><template #default="scope"><el-button link type="primary" @click="openCheckin(scope.row)">打卡</el-button><el-dropdown @command="(command: string) => pointAction(command, scope.row)"><el-button link type="primary">更多</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="skip">跳过</el-dropdown-item><el-dropdown-item command="undo">撤销打卡</el-dropdown-item><el-dropdown-item command="current">设为当前点</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></el-table-column></el-table>
      </template>
    </section>
    <el-dialog v-model="startOpen" title="开始新出行" width="560px" append-to-body :close-on-click-modal="false" :before-close="beforeClose"><el-form ref="startFormRef" :model="startForm" :rules="startRules" label-width="100px"><el-form-item label="路书" prop="routebookId"><routebook-select v-model="startForm.routebookId" /></el-form-item><div class="form-grid"><el-form-item label="起点经度"><el-input-number v-model="startForm.lng" :precision="6" /></el-form-item><el-form-item label="起点纬度"><el-input-number v-model="startForm.lat" :precision="6" /></el-form-item></div><el-form-item label="客户端类型"><el-select v-model="startForm.clientType" style="width:100%"><el-option v-for="item in trip_client_type" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item></el-form><template #footer><el-button :disabled="submitting" @click="startOpen = false">取消</el-button><el-button type="primary" :loading="submitting" @click="submitStart">开始出行</el-button></template></el-dialog>
    <el-dialog v-model="locationOpen" title="定位匹配" width="560px" append-to-body :close-on-click-modal="false" :before-close="beforeClose"><el-form label-width="100px"><div class="form-grid"><el-form-item label="当前经度"><el-input-number v-model="locationForm.lng" :precision="6" /></el-form-item><el-form-item label="当前纬度"><el-input-number v-model="locationForm.lat" :precision="6" /></el-form-item></div><el-form-item label="定位精度"><el-input-number v-model="locationForm.accuracy" :min="0" /><span class="unit">米</span></el-form-item><el-form-item label="客户端类型"><el-select v-model="locationForm.clientType" style="width:100%"><el-option v-for="item in trip_client_type" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item></el-form><template #footer><el-button :disabled="submitting" @click="locationOpen = false">取消</el-button><el-button type="primary" :loading="submitting" @click="submitLocation">匹配当前位置</el-button></template></el-dialog>
    <el-dialog v-model="checkinOpen" title="点位打卡" width="560px" append-to-body :close-on-click-modal="false" :before-close="beforeClose"><el-form ref="checkinFormRef" :model="checkinForm" :rules="checkinRules" label-width="100px"><el-form-item label="点位 ID" prop="pointId"><el-input-number v-model="checkinForm.pointId" :min="1" /></el-form-item><div class="form-grid"><el-form-item label="打卡经度"><el-input-number v-model="checkinForm.lng" :precision="6" /></el-form-item><el-form-item label="打卡纬度"><el-input-number v-model="checkinForm.lat" :precision="6" /></el-form-item></div><el-form-item label="打卡方式"><el-select v-model="checkinForm.checkinType"><el-option v-for="item in trip_checkin_type" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item><el-form-item label="备注"><el-input v-model="checkinForm.remark" type="textarea" :rows="3" /></el-form-item></el-form><template #footer><el-button :disabled="submitting" @click="checkinOpen = false">取消</el-button><el-button type="primary" :loading="submitting" @click="submitCheckin">确认打卡</el-button></template></el-dialog>
  </business-page>
</template>

<script setup lang="ts" name="TripJourney">
import { ElMessage, ElMessageBox } from 'element-plus'
import BusinessPage from '@/components/BusinessPage/index.vue'; import PageState from '@/components/BusinessPage/PageState.vue'
import RoutebookSelect from '@/components/RoutebookSelect/index.vue'
import { cancelJourney, checkinJourneyPoint, finishJourney, getJourney, matchJourneyLocation, setCurrentJourneyPoint, skipJourneyPoint, startJourney, undoJourneyCheckin } from '@/api/trip/journey'
import type { TripJourneyCheckinRequest, TripJourneyDetail, TripJourneyLocationRequest, TripJourneyStartRequest } from '@/types/api/trip/journeyBusiness'
type TripJourneyStartForm = Omit<TripJourneyStartRequest, 'routebookId'> & { routebookId?: number }
const { trip_journey_status, trip_journey_point_status, trip_client_type, trip_checkin_type } = useDict('trip_journey_status', 'trip_journey_point_status', 'trip_client_type', 'trip_checkin_type')
const journeyId = ref<number>(); const detail = ref<TripJourneyDetail>(); const loading = ref(false); const loadError = ref(false); const submitting = ref(false)
const startOpen = ref(false); const locationOpen = ref(false); const checkinOpen = ref(false); const startFormRef = ref<any>(); const checkinFormRef = ref<any>(); const startForm = ref<TripJourneyStartForm>({ clientType: 'WEB' }); const locationForm = ref<TripJourneyLocationRequest>({ journeyId: 0, lng: 0, lat: 0, clientType: 'WEB' }); const checkinForm = ref<TripJourneyCheckinRequest>({ journeyId: 0, checkinType: 'MANUAL' })
const startRules: Record<string, any[]> = { routebookId: [{ required: true, message: '请选择路书', trigger: 'change' }] }; const checkinRules: Record<string, any[]> = { pointId: [{ required: true, message: '请填写点位 ID', trigger: 'change' }] }
const journeyPoints = computed<Record<string, any>[]>(() => Array.isArray(detail.value?.points) ? detail.value!.points as Record<string, any>[] : [])
async function loadJourney(): Promise<void> { if (!journeyId.value) { ElMessage.warning('请输入出行实例 ID'); return } loading.value = true; loadError.value = false; try { const response = await getJourney(journeyId.value); detail.value = response.data } catch (error) { loadError.value = true; console.warn('出行实例加载失败，请核对实例 ID。', error) } finally { loading.value = false } }
function openStart(): void { startForm.value = { clientType: 'WEB' }; startOpen.value = true; nextTick(() => startFormRef.value?.clearValidate()) }
async function submitStart(): Promise<void> { await startFormRef.value?.validate(); submitting.value = true; try { const response: any = await startJourney({ ...startForm.value, routebookId: Number(startForm.value.routebookId) }); const data = response.data || {}; journeyId.value = Number(data.id || data.journeyId); ElMessage.success('出行已开始'); startOpen.value = false; if (journeyId.value) await loadJourney() } catch (error) { console.warn('开始出行失败，请检查路书状态和起点参数。', error) } finally { submitting.value = false } }
async function submitLocation(): Promise<void> { submitting.value = true; try { await matchJourneyLocation({ ...locationForm.value, journeyId: Number(journeyId.value) }); ElMessage.success('定位匹配完成'); locationOpen.value = false; await loadJourney() } catch (error) { console.warn('定位匹配失败，请检查定位参数。', error) } finally { submitting.value = false } }
function openCheckin(row?: Record<string, any>): void { checkinForm.value = { journeyId: Number(journeyId.value), pointId: row?.pointId || detail.value?.currentPointId, checkinType: 'MANUAL' }; checkinOpen.value = true; nextTick(() => checkinFormRef.value?.clearValidate()) }
async function submitCheckin(): Promise<void> { await checkinFormRef.value?.validate(); submitting.value = true; try { await checkinJourneyPoint(checkinForm.value); ElMessage.success('打卡成功'); checkinOpen.value = false; await loadJourney() } catch (error) { console.warn('点位打卡失败，请检查点位和定位信息。', error) } finally { submitting.value = false } }
async function pointAction(command: string, row: Record<string, any>): Promise<void> { const data = { journeyId: Number(journeyId.value), pointId: Number(row.pointId) }; if (command === 'skip') await skipJourneyPoint(data); if (command === 'undo') await undoJourneyCheckin(data); if (command === 'current') await setCurrentJourneyPoint(data); ElMessage.success('操作成功'); await loadJourney() }
async function finish(): Promise<void> { await ElMessageBox.confirm('结束后本次出行将进入完成状态，确定吗？', '结束出行', { type: 'warning' }); await finishJourney({ journeyId: Number(journeyId.value) }); ElMessage.success('出行已结束'); await loadJourney() }
async function cancel(): Promise<void> { const result = await ElMessageBox.prompt('请输入取消原因', '取消出行', { inputType: 'textarea' }); await cancelJourney({ journeyId: Number(journeyId.value), reason: result.value }); ElMessage.success('出行已取消'); await loadJourney() }
function beforeClose(done: () => void): void { if (!submitting.value) done() }
</script>

<style scoped lang="scss">
.business-panel{border:1px solid var(--roadbook-border);border-radius:var(--roadbook-radius);background:var(--roadbook-panel-bg);box-shadow:var(--roadbook-shadow)}.lookup-bar{display:flex;padding:16px;margin-bottom:16px;gap:8px}.content-panel{min-height:420px;padding:22px}.journey-header{display:flex;align-items:flex-start;justify-content:space-between}.journey-header span,.journey-header p{color:var(--roadbook-text-secondary)}.journey-header h2{margin:6px 0}.metric-row{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:20px 0}.metric-row article{padding:16px;border-radius:10px;background:var(--roadbook-panel-muted)}.metric-row small,.metric-row strong{display:block}.metric-row strong{margin-top:8px;font-size:22px}.journey-actions{display:flex;flex-wrap:wrap;gap:8px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.unit{margin-left:8px;color:var(--roadbook-text-secondary)}@media(max-width:720px){.metric-row{grid-template-columns:repeat(2,1fr)}.form-grid{grid-template-columns:1fr}}
</style>
